def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    """Read an attribute or mapping key from an object.

    Perplexity SDK responses are Pydantic models, but tests and streamed events may
    surface plain dicts. This helper reads uniformly from either.

    Args:
        obj: The object or mapping to read from.
        key: The attribute name or mapping key to look up.
        default: Value returned when the key or attribute is absent.

    Returns:
        The resolved value, or `default` if it cannot be found.
    """
    if obj is None:
        return default
    if isinstance(obj, Mapping):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _maybe_dump(obj: Any) -> Any:
    """Return `model_dump()` output for Pydantic models, else the object unchanged."""
    if hasattr(obj, "model_dump"):
        return obj.model_dump()
    return obj


def _is_builtin_tool(tool: Any) -> bool:
    """Return `True` if `tool` is a Perplexity built-in (non-function) tool."""
    if isinstance(tool, str):
        return True
    if isinstance(tool, Mapping):
        return tool.get("type") not in (None, "function")
    tool_type = getattr(tool, "type", None)
    return tool_type not in (None, "function")


def _use_responses_api(payload: dict) -> bool:
    """Decide whether a payload should be routed to the Perplexity Responses API.

    Args:
        payload: The request payload built from default params, model kwargs and
            call-time kwargs.

    Returns:
        `True` if the payload contains any built-in (non-function) tool or a
        Responses-only key (`previous_response_id`, `instructions`, `input`,
        `include`); `False` otherwise (e.g. only function-type tools or no tools).
    """
    tools = payload.get("tools") or []
    uses_builtin_tools = any(_is_builtin_tool(tool) for tool in tools)
    return bool(uses_builtin_tools or _RESPONSES_ONLY_KEYS.intersection(payload))


def _convert_responses_usage(usage: Any) -> dict | None:
    """Convert Perplexity Responses API usage into LangChain `UsageMetadata`.

    Args:
        usage: The `usage` object (or mapping) from a Responses API response.

    Returns:
        A `UsageMetadata` dict, or `None` if every token field is `None`. When only
        `input_tokens` and `output_tokens` are present, `total_tokens` is derived
        from their sum.
    """
    if usage is None:
        return None
    input_tokens = _obj_get(usage, "input_tokens")
    output_tokens = _obj_get(usage, "output_tokens")
    total_tokens = _obj_get(usage, "total_tokens")
    if input_tokens is None and output_tokens is None and total_tokens is None:
        return None
    if total_tokens is None and input_tokens is not None and output_tokens is not None:
        total_tokens = input_tokens + output_tokens
    return UsageMetadata(
        input_tokens=input_tokens or 0,
        output_tokens=output_tokens or 0,
        total_tokens=total_tokens or 0,
    )


def _extract_responses_text(response: Any) -> str:
    """Extract assistant text from a Responses API response.

    Prefers the convenience `output_text` attribute, falling back to concatenating
    `output_text` content parts from message items in the `output` list.

    Args:
        response: The Responses API response object or mapping.

    Returns:
        The aggregated assistant text (may be an empty string).
    """
    text = _obj_get(response, "output_text")
    if text:
        return text
    texts: list[str] = []
    for item in _obj_get(response, "output") or []:
        if _obj_get(item, "type") == "message":
            for part in _obj_get(item, "content") or []:
                if _obj_get(part, "type") == "output_text":
                    texts.append(_obj_get(part, "text") or "")
    return "".join(texts)


def _extract_responses_extras(response: Any) -> dict[str, Any]:
    """Collect Perplexity-specific extras from a Responses API response.

    Args:
        response: The Responses API response object or mapping.

    Returns:
        A dict suitable for `additional_kwargs`, containing search results pulled
        from `search_results` output items and any top-level `citations`, `images`
        or `related_questions` fields.
    """
    extras: dict[str, Any] = {}
    search_results: list[Any] = []
    for item in _obj_get(response, "output") or []:
        if _obj_get(item, "type") == "search_results":
            results = _obj_get(item, "results")
            if results:
                search_results.extend(_maybe_dump(r) for r in results)
    if search_results:
        extras["search_results"] = search_results
    for attr in ("citations", "images", "related_questions"):
        value = _obj_get(response, attr)
        if value:
            extras[attr] = value
    return extras


def _responses_response_metadata(response: Any) -> dict[str, Any]:
    """Build `response_metadata` from a Responses API response or event response."""
    response_metadata: dict[str, Any] = {}
    for key in ("id", "model", "status", "object", "created_at"):
        value = _obj_get(response, key)
        if value is not None:
            response_metadata[key] = value
    if "model" in response_metadata:
        response_metadata["model_name"] = response_metadata["model"]
    return response_metadata


